'use client'

import { usePathname } from 'next/navigation'
import { useLayoutEffect, useRef } from 'react'

function depth(pathname: string) {
  return pathname.split('/').filter(Boolean).length
}

/**
 * Tags <html> with data-nav-direction="forward" | "back" so the
 * view-transition CSS in globals.css can slide pages directionally.
 * Runs in a layout effect, which React commits inside the view
 * transition's update callback — before the animation styles are resolved.
 */
export function NavigationDirection() {
  const pathname = usePathname()
  const previousPathname = useRef(pathname)

  useLayoutEffect(() => {
    if (pathname === previousPathname.current) return
    document.documentElement.dataset.navDirection =
      depth(pathname) > depth(previousPathname.current) ? 'forward' : 'back'
    previousPathname.current = pathname
  }, [pathname])

  return null
}

