/* --- View transitions --------------------------------------------------- */

/* Shared timing for all transition groups (incl. the product image morph). */
::view-transition-group(*) {
  animation-duration: 300ms;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

/* Directional page slide. The `page` name is assigned by the
   <ViewTransition name="page"> wrapper in app/layout.tsx; the
   data-nav-direction attribute is set by app/NavigationDirection.tsx. */
::view-transition-old(page),
::view-transition-new(page) {
  animation-duration: 300ms;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

html[data-nav-direction='forward']::view-transition-old(page) {
  animation-name: slide-out-to-left;
}

html[data-nav-direction='forward']::view-transition-new(page) {
  animation-name: slide-in-from-right;
}

html[data-nav-direction='back']::view-transition-old(page) {
  animation-name: slide-out-to-right;
}

html[data-nav-direction='back']::view-transition-new(page) {
  animation-name: slide-in-from-left;
}

@keyframes slide-out-to-left {
  to {
    opacity: 0;
    transform: translateX(-3rem);
  }
}

@keyframes slide-in-from-right {
  from {
    opacity: 0;
    transform: translateX(3rem);
  }
}

@keyframes slide-out-to-right {
  to {
    opacity: 0;
    transform: translateX(3rem);
  }
}

@keyframes slide-in-from-left {
  from {
    opacity: 0;
    transform: translateX(-3rem);
  }
}

/* Suspense skeleton -> content cross-fade (class set via
   <ViewTransition default="suspense-content">). */
::view-transition-old(*.suspense-content),
::view-transition-new(*.suspense-content) {
  animation-duration: 350ms;
  animation-timing-function: ease;
}

/* --- Reduced motion ------------------------------------------------------ */

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-image-pair(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }

  .skeleton-image,
  .skeleton-text {
    animation: none;
  }
}

